import 'package:flutter/material.dart';
import '../../models/story.dart';
import '../../services/tts_service.dart';

class AudioPlayerScreen extends StatefulWidget { final Story story; const AudioPlayerScreen({super.key,required this.story}); @override State<AudioPlayerScreen> createState()=>_AudioPlayerScreenState(); }
class _AudioPlayerScreenState extends State<AudioPlayerScreen>{bool english=false;bool playing=false;final tts=TtsService();@override void dispose(){tts.stop();super.dispose();}Future<void> toggle()async{if(playing){await tts.stop();setState(()=>playing=false);}else{setState(()=>playing=true);await tts.speak(english?widget.story.englishContent:widget.story.content,english:english);if(mounted)setState(()=>playing=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Listen')),body:Center(child:Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[ClipRRect(borderRadius:BorderRadius.circular(28),child:Image.asset(widget.story.image,width:280,height:280,fit:BoxFit.cover)),const SizedBox(height:25),Text(english?widget.story.englishTitle:widget.story.title,textAlign:TextAlign.center,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:18),Row(children:[Expanded(child:ChoiceChip(label:const Text('Hausa'),selected:!english,onSelected:(_){setState(()=>english=false);})),Expanded(child:ChoiceChip(label:const Text('English'),selected:english,onSelected:(_){setState(()=>english=true);})),]),const SizedBox(height:28),IconButton.filled(onPressed:toggle,icon:Icon(playing?Icons.stop_rounded:Icons.play_arrow_rounded),iconSize:42,padding:const EdgeInsets.all(20)),const SizedBox(height:14),Text(playing?'Ana sauraro…':'Danna don sauraro',style:const TextStyle(fontWeight:FontWeight.w800))]))));}
